fn is_digit(c: Str) -> Bool {
    return c == "0" or c == "1" or c == "2" or c == "3" or c == "4" or c == "5" or c == "6" or c == "7" or c == "8" or c == "9"
}

fn digit_value(c: Str) -> Int {
    if c == "0" {
        return 0
    }
    if c == "1" {
        return 1
    }
    if c == "2" {
        return 2
    }
    if c == "3" {
        return 3
    }
    if c == "4" {
        return 4
    }
    if c == "5" {
        return 5
    }
    if c == "6" {
        return 6
    }
    if c == "7" {
        return 7
    }
    if c == "8" {
        return 8
    }
    return 9
}

pub fn duration(s: Str) -> Result[Int, Str] {
    var total = 0
    var num = 0
    var have_digits = false
    var last_rank = -1
    var seen_any = false

    for c in s.chars() {
        if is_digit(c) {
            num = num * 10 + digit_value(c)
            have_digits = true
        } else {
            var rank = -1
            var mult = 0
            if c == "d" {
                rank = 0
                mult = 86400
            } else if c == "h" {
                rank = 1
                mult = 3600
            } else if c == "m" {
                rank = 2
                mult = 60
            } else if c == "s" {
                rank = 3
                mult = 1
            } else {
                return Err("invalid duration")
            }
            if not have_digits or rank <= last_rank {
                return Err("invalid duration")
            }
            total = total + num * mult
            num = 0
            have_digits = false
            last_rank = rank
            seen_any = true
        }
    }

    if have_digits or not seen_any {
        return Err("invalid duration")
    }
    return Ok(total)
}
